var msg = $json;

// Gmail search already provides Subject, From, To in the item
var from = msg.From || msg.from || '';
var subject = msg.Subject || msg.subject || '';
var to = msg.To || msg.to || '';
var date = msg.date || msg.Date || '';

// Extract body text from payload
var body = '';
if (msg.payload && msg.payload.parts) {
  var textPart = null;
  var htmlPart = null;
  for (var i = 0; i < msg.payload.parts.length; i++) {
    if (msg.payload.parts[i].mimeType === 'text/plain') textPart = msg.payload.parts[i];
    if (msg.payload.parts[i].mimeType === 'text/html') htmlPart = msg.payload.parts[i];
  }
  if (textPart && textPart.body && textPart.body.data) {
    body = Buffer.from(textPart.body.data, 'base64').toString('utf8');
  } else if (htmlPart && htmlPart.body && htmlPart.body.data) {
    body = Buffer.from(htmlPart.body.data, 'base64').toString('utf8');
  }
} else if (msg.payload && msg.payload.body && msg.payload.body.data) {
  body = Buffer.from(msg.payload.body.data, 'base64').toString('utf8');
} else if (msg.snippet) {
  body = msg.snippet;
}

return [{
  json: {
    id: msg.id,
    threadId: msg.threadId,
    snippet: msg.snippet,
    from_email: from,
    from_name: from.split('<')[0] ? from.split('<')[0].trim() : from,
    from_address: (from.match(/<([^>]+)>/) || [])[1] || from,
    subject: subject,
    date: date,
    to: to,
    body: body.substring(0, 8000),
    body_preview: body.substring(0, 500)
  }
}];

var email = $json;
var text = ((email.subject || '') + ' ' + (email.body || '')).toLowerCase();

var cvMap = [
  { keywords: ['azure','microsoft','entra','m365'], cv: 'cv_azure_architect.pdf', techStack: 'Azure Cloud Architect' },
  { keywords: ['aws','amazon web services','ec2','s3'], cv: 'cv_aws_architect.pdf', techStack: 'AWS Solutions Architect' },
  { keywords: ['kubernetes','k8s','docker'], cv: 'cv_kubernetes_engineer.pdf', techStack: 'Kubernetes Engineer' },
  { keywords: ['devops','cicd','pipeline'], cv: 'cv_devops_engineer.pdf', techStack: 'DevOps Engineer' },
  { keywords: ['security','soc','cyber'], cv: 'cv_security_engineer.pdf', techStack: 'Security Engineer' },
  { keywords: ['ai','machine learning','ml','generative ai'], cv: 'cv_ai_engineer.pdf', techStack: 'AI Engineer' },
  { keywords: ['data','databricks','spark'], cv: 'cv_data_engineer.pdf', techStack: 'Data Engineer' }
];

var best = { cv: 'cv_ai_engineer.pdf', techStack: 'AI Engineer' };
var maxScore = 0;
for (var i = 0; i < cvMap.length; i++) {
  var score = 0;
  for (var j = 0; j < cvMap[i].keywords.length; j++) {
    if (text.indexOf(cvMap[i].keywords[j]) !== -1) {
      score++;
    }
  }
  if (score > maxScore) {
    maxScore = score;
    best = cvMap[i];
  }
}

var baseUrl = 'https://raw.githubusercontent.com/rifaterdemsahin/CVLauncher/main/5_Symbols/cvs/';

return [{
  json: {
    id: email.id,
    threadId: email.threadId,
    snippet: email.snippet,
    from_email: email.from_email,
    from_name: email.from_name,
    from_address: email.from_address,
    subject: email.subject,
    date: email.date,
    to: email.to,
    body: email.body,
    body_preview: email.body_preview,
    selected_cv: best.cv,
    tech_stack: best.techStack,
    cv_download_url: baseUrl + best.cv
  }
}];

var email = $json;
var body = (email.body || '').toLowerCase();
var subject = (email.subject || '').toLowerCase();
var text = subject + ' ' + body;

// Detect role type
var roleType = 'opportunity';
if (text.indexOf('devops') !== -1) roleType = 'DevOps role';
else if (text.indexOf('azure') !== -1) roleType = 'Azure role';
else if (text.indexOf('aws') !== -1) roleType = 'AWS role';
else if (text.indexOf('kubernetes') !== -1 || text.indexOf('k8s') !== -1) roleType = 'Kubernetes role';
else if (text.indexOf('security') !== -1) roleType = 'Security role';
else if (text.indexOf('ai') !== -1 || text.indexOf('machine learning') !== -1) roleType = 'AI/ML role';
else if (text.indexOf('data') !== -1) roleType = 'Data role';
else if (text.indexOf('contract') !== -1) roleType = 'contract role';
else if (text.indexOf('permanent') !== -1) roleType = 'permanent role';

var response = 'Thank you for reaching out regarding the ' + roleType + '.\n\n' +
  'I am a DevOps & Cloud Architect with 20+ years of experience designing, building, and securing scalable platforms for enterprise clients. ' +
  'My expertise spans Azure, AWS, Kubernetes, CI/CD, and Infrastructure as Code. ' +
  'I have delivered critical national infrastructure projects and have a strong track record in high-stakes environments.\n\n' +
  'I would be happy to discuss how my background aligns with your requirements. ' +
  'Please find my CV attached, and feel free to reach out directly if you would like to arrange a call.\n\n' +
  'Looking forward to hearing from you.';

return [{
  json: {
    ...email,
    response: response,
    role_type: roleType
  }
}];

var email = $json;
var gen = (email.response || 'Thank you for reaching out.');

var html = '<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">' +
  '<p>Hi,</p>' +
  '<p>' + gen + '</p>' +
  '<div style="margin: 20px 0; padding: 15px; background-color: #f9f9f9; border-left: 4px solid #007bff;">' +
    '<p><strong>📄 <a href="' + email.cv_download_url + '" style="text-decoration: none; color: #007bff;">View CV — ' + email.tech_stack + ' (PDF)</a></strong></p>' +
    '<p><strong>📅 <a href="https://calendly.com/rifaterdem/schedule" style="text-decoration: none; color: #007bff;">Book a clear intro call</a></strong></p>' +
  '</div>' +
  '<p>Best regards,</p>' +
  '<p><strong>Rifat Erdem Sahin</strong></p>' +
  '<p style="font-size: 14px; color: #7f8c8d;">Director | DevOps & Cloud Architect | Pexabo<br>+44 7848 024173 | contact@rifaterdemsahin.com</p>' +
'</div>';

return [{
  json: {
    ...email,
    reply_body: html,
    reply_text: gen
  }
}];
